<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;
class CurriculumScheduleBinder{
 public function bind(int $planId,bool $rebuild=false):array{$cp=DB::table('curriculum_plans')->find($planId);if(!$cp)return ['bound'=>0,'unassigned'=>0];$topics=DB::table('curriculum_topics')->where('curriculum_plan_id',$planId)->orderBy('sort_order')->get();$lessons=DB::table('lesson_occurrences')->where(['academic_period_id'=>$cp->academic_period_id,'study_group_id'=>$cp->study_group_id,'subject_id'=>$cp->subject_id])->whereNotIn('status',['cancelled'])->orderBy('lesson_date')->orderBy('lesson_number')->get();$today=now()->toDateString();if($rebuild){DB::table('lesson_occurrences')->where(['academic_period_id'=>$cp->academic_period_id,'study_group_id'=>$cp->study_group_id,'subject_id'=>$cp->subject_id,'curriculum_auto_bound'=>1])->where('lesson_date','>',$today)->update(['curriculum_topic_id'=>null,'curriculum_auto_bound'=>0,'updated_at'=>now()]);$lessons=DB::table('lesson_occurrences')->where(['academic_period_id'=>$cp->academic_period_id,'study_group_id'=>$cp->study_group_id,'subject_id'=>$cp->subject_id])->whereNotIn('status',['cancelled'])->orderBy('lesson_date')->orderBy('lesson_number')->get();}$queue=[];foreach($topics as $t){$slots=max(1,(int)ceil((float)$t->planned_hours));for($i=0;$i<$slots;$i++)$queue[]=$t->id;}$n=0;$i=0;foreach($lessons as $l){if($l->curriculum_topic_id){$i++;continue;}if(!isset($queue[$i]))break;DB::table('lesson_occurrences')->where('id',$l->id)->update(['curriculum_topic_id'=>$queue[$i],'curriculum_auto_bound'=>1,'updated_at'=>now()]);$n++;$i++;}return ['bound'=>$n,'unassigned'=>max(0,count($queue)-$i),'lessons'=>$lessons->count(),'topics'=>$topics->count()];}
 public function bindPeriod(int $periodId,bool $rebuild=false):array{$plans=DB::table('curriculum_plans')->where('academic_period_id',$periodId)->where('status','active')->pluck('id');$r=['plans'=>$plans->count(),'bound'=>0,'unassigned'=>0];foreach($plans as $id){$x=$this->bind($id,$rebuild);$r['bound']+=$x['bound'];$r['unassigned']+=$x['unassigned'];}return $r;}
}